      ["mirror_r", function (i, j, g) { return _par(g, i + 1, j + 1); }],
      ["mirror_rows", function (i, j, g) { return (i % 2) ? G.flipV(g) : g; }],
      ["mirror_cols", function (i, j, g) { return (j % 2) ? G.flipH(g) : g; }],
      ["rot_cycle", function (i, j, g) { return _rotc(g, (i + j) % 4); }]
