      (function (name, f) {
        out.push(_h("union_" + name, function (g) { return _union(g, f(g), bg); }, 3.2));
        out.push(_h("union_" + name + "_rev", function (g) { return _union(f(g), g, bg); }, 3.4));
      })(G.DIHEDRAL[i][0], G.DIHEDRAL[i][1]);
