    and: function (n, t) { return n === t; },
    or: function (n, t) { return n > 0; },
    xor: function (n, t) { return n === 1; },
    nand: function (n, t) { return n < t; },
    nor: function (n, t) { return n === 0; },
    xnor: function (n, t) { return n !== 1; },
    majority: function (n, t) { return 2 * n > t; },
