      for (i = 0; i < cells.length; i++) cnt.set(cells[i], (cnt.get(cells[i]) || 0) + 1);
      var items = [];
      cnt.forEach(function (n, v) { items.push([v, n]); });
      items.sort(function (a, b) { return (b[1] - a[1]) || (a[0] - b[0]); });
