        hits = _occurrences(ctx.train[t][0], pre);
        if (!hits.length) { ok = false; break; }
        h = pre.length; w = pre[0].length;
        set2 = new Set();
        for (j = 0; j < hits.length; j++)
          set2.add(hits[j][0] + "," + hits[j][1] + "," + (hits[j][0] + h - 1) + "," + (hits[j][1] + w - 1));
        targets.push(set2);
