  geometry: 0.0, cellwise: 1.0, partition: 0.0, symmetry: 0.0,
  objects: 1.5, tiling: 0.5, colormap: 0.0, select: 1.0,
  compose: 2.5, enumerate: 3.0, sequence: 1.0
